<template>
    <div class="home">
        <div class="tree-container">
            <div class="relation" ref="graphContainer"></div>
        </div>
        <el-dialog
                :title="'对'+currentNode.name+'操作'"
                :visible.sync="showToolMenu"
                v-if="currentNode!=null"
                :close-on-click-modal="false"
        >
            <div class="btns">
                <div class="hf">
                    <el-button type="primary" @click="editPerson" icon="el-icon-edit">编辑信息</el-button>
                </div>
                <div class="hf">
                    <el-popconfirm title="确定要删除这个节点吗？" @confirm="deleteNode">
                        <el-button type="warning" slot="reference" icon="el-icon-delete">删除人物</el-button>
                    </el-popconfirm>
                </div>
                <div class="hf">
                    <el-button type="success" @click="addLink" icon="el-icon-link">建立关系</el-button>
                </div>
                <div class="hf">
                    <el-button type="success" @click="listLink" icon="el-icon-cpu">管理关系</el-button>
                </div>
            </div>
        </el-dialog>
        <el-dialog
                :title="whichTitle"
                :visible.sync="showPerson"
                :close-on-click-modal="false"
        >
            <el-form :model="editForm" status-icon :rules="rules" ref="editForm" label-width="60px">
                <el-form-item label="头像" prop="photo">
                    <!--                    <el-input v-model="editForm.photo"></el-input>-->
                    <el-upload
                            class="avatar-uploader" :class="{tx:editForm.photo}"
                            action="https://jsonplaceholder.typicode.com/posts/"
                            :show-file-list="false"
                            :on-success="handleAvatarSuccess"
                            :before-upload="beforeAvatarUpload">
                        <template v-if="editForm.photo">
                            <img :src="editForm.photo" class="avatar">
                            <i class="el-icon-delete" @click.stop="handleRemove"></i>
                        </template>
                        <i v-else class="el-icon-plus avatar-uploader-icon"></i>
                    </el-upload>
                    <el-input v-model="editForm.photo"></el-input>
                </el-form-item>
                <el-form-item label="姓名" prop="name">
                    <el-input v-model="editForm.name"></el-input>
                </el-form-item>
                <el-form-item label="别名">
                    <el-input v-model="editForm.alias"></el-input>
                </el-form-item>
                <el-form-item label="性別" prop="gender">
                    <el-radio-group v-model="editForm.gender">
                        <el-radio label="男">男</el-radio>
                        <el-radio label="女">女</el-radio>
                        <el-radio label="无">无</el-radio>
                        <el-radio label="物">物</el-radio>
                        <el-radio label="文字">文字</el-radio>
                    </el-radio-group>
                </el-form-item>
                <el-form-item label="颜色" v-if="editForm.gender=='文字'||editForm.gender=='物'">
                        <el-color-picker v-model="editForm.color"></el-color-picker>
                </el-form-item>
                <el-form-item label="宽度" v-if="editForm.gender=='文字'">
                    <el-radio-group v-model="editForm.textWidth">
                        <el-radio label="auto">自动</el-radio>
                        <el-input v-model="editForm.textWidth"></el-input>
                    </el-radio-group>
                </el-form-item>
                <el-form-item label="位置" v-if="editForm.gender=='文字'&&(editForm.textWidth!='auto'&&editForm.textWidth!=undefined)">
                    <el-radio-group v-model="editForm.textPo">
                        <el-radio label="bottom">下</el-radio>
                        <el-radio label="top">上</el-radio>
                    </el-radio-group>
                </el-form-item>
                <div style="display: flex;">
                    <el-col>
                        <el-form-item label="出生">
                            <el-date-picker type="date" placeholder="选择日期"
                                            v-model="editForm.birthDate" value-format="yyyy-MM-dd"></el-date-picker>
                        </el-form-item>
                    </el-col>
                    <el-col>
                        <el-form-item label="死亡">
                            <el-date-picker type="date" placeholder="选择日期"
                                            v-model="editForm.deathDate" value-format="yyyy-MM-dd"></el-date-picker>
                        </el-form-item>
                    </el-col>
                </div>
                <el-form-item label="介绍">
                    <el-input type="textarea" v-model="editForm.details" rows="6"></el-input>
                </el-form-item>
                <el-form-item>
                    <el-button type="primary" @click="submitForm('editForm')">提交</el-button>
                </el-form-item>
            </el-form>
        </el-dialog>
        <el-dialog
                :title="whichTitleLink"
                :visible.sync="showLink"
                :close-on-click-modal="false"
        >
            <el-form :model="linkForm" status-icon :rules="rulesL" ref="linkForm" label-width="80px">
                <el-form-item label="关系源" prop="source">
                    <el-input v-model="linkForm.source" v-if="currentNode" disabled></el-input>
                    <el-input v-model="linkForm.source" v-else></el-input>
                </el-form-item>
                <el-form-item label="关系目标" prop="target">
                    <el-input v-model="linkForm.target" v-if="currentLink" disabled>></el-input>
                    <el-input v-model="linkForm.target" v-else></el-input>
                </el-form-item>
                <el-form-item label="关系类型" prop="type">
                    <el-input v-model="linkForm.type"></el-input>
                </el-form-item>
                <el-form-item label="介绍">
                    <el-input type="textarea" v-model="linkForm.details" rows="6"></el-input>
                </el-form-item>
                <el-form-item>
                    <el-button type="primary" @click="submitForm1('linkForm')">提交</el-button>
                </el-form-item>
            </el-form>
        </el-dialog>
        <el-dialog
                :title="linkList"
                :visible.sync="showLinkList"
                :close-on-click-modal="false"
        >
            <ul class="linkList">
                <li v-for="item in currentLinkList">
                    <div class="ti">
                        <span class="yellow">{{toName(item.source.id)}}</span>的<span class="yellow">{{item.type}}</span>是<span
                            class="yellow">{{toName(item.target.id)}}</span>
                    </div>
                    <div class="dos">
                        <i class="el-icon-edit" @click="editLink(item)"></i>
                        <i class="el-icon-delete-solid" @click="deleteLink(item)"></i>
                    </div>

                </li>
            </ul>
        </el-dialog>
        <el-dialog
                title="关系说明"
                :visible.sync="showLinkDetails"
                v-if="currentLink!=null&&currentLink.details!=null&&currentLink.details!=''"
                :close-on-click-modal="false"
        >
            <div v-html="currentLink.details" style="line-height: 1.8em"></div>
        </el-dialog>
        <div class="tools">
            <div @click="saveImg" class="to to1">
                <i class="el-icon-camera-solid"></i>
            </div>
            <div @click="addPerson" class="to to2">
                <i class="el-icon-user-solid"></i>
            </div>
            <router-link to="/" class="to to3">
                <i class="el-icon-back"></i>
            </router-link>
        </div>
    </div>
</template>

<script>
    import html2canvas from 'html2canvas';
    import * as d3 from "d3";

    export default {
        name: 'Home',
        data() {
            let validateName = (rule, value, callback) => {
                if (value === '') {
                    callback(new Error('请输入姓名'));
                } else {
                    callback();
                }
            };
            let validateSource = (rule, value, callback) => {
                if (value === '') {
                    callback(new Error('请输入关系源'));
                } else {
                    callback();
                }
            };
            let validateTarget = (rule, value, callback) => {
                if (value === '') {
                    callback(new Error('请输入关系目标'));
                } else {
                    callback();
                }
            };
            let validateType = (rule, value, callback) => {
                if (value === '') {
                    callback(new Error('请输入关系类型'));
                } else {
                    callback();
                }
            };
            return {
                relationName: '',
                persons: [],
                links: [],
                showPerson: false,
                showLink: false,
                showLinkList: false,
                showToolMenu: false,
                showLinkDetails: false,//关系说明窗口
                editPersonsMode: 'add', // 'add' 或 'edit'
                editLinksMode: 'add', // 'add' 或 'edit'
                editForm: {
                    photo: '',
                    name: '',
                    alias: '',
                    gender: '男性',
                    textWidth: 'auto',
                    textPo:'bottom',
                    color:'#fa0',
                    birthDate: '',
                    deathDate: '',
                    details: ''
                },
                rules: {
                    name: [
                        {required: true, validator: validateName, trigger: 'blur'}
                    ],
                },
                linkForm: {
                    source: '',
                    target: '',
                    type: '',
                    details: ''
                },
                rulesL: {
                    source: [
                        {required: true, validator: validateSource, trigger: 'blur'}
                    ],
                    target: [
                        {required: true, validator: validateTarget, trigger: 'blur'}
                    ],
                    type: [
                        {required: true, validator: validateType, trigger: 'blur'}
                    ],
                },
                currentNode: null,
                currentLink: null,
                captureWidth: 1920,
                captureHeight: 1080,
                routeId: this.$route.params.id,
            }
        },
        mounted() {
            window.addEventListener('resize', () => {
                this.drawGraph()
            })

        },
        watch: {
            showLinkDetails: {
                handler(value) {
                    if (!value) {
                        this.currentLink = null
                    }
                },
                immediate: true
            },
            showToolMenu: {
                handler(value) {
                    if (!value) {
                        this.currentNode = null
                    }
                },
                immediate: true
            },
            currentNode: {
                handler(value) {
                    if (value) {
                        this.linkForm.source = value.name
                    }
                },
                immediate: false
            },
            $route: {
                handler(route) {
                    this.routeId = route.params.id
                    if (this.$store.state.relation.relation === null) {
                        this.$store.dispatch('relation/getAll').then((rs) => {
                            let fi = rs.filter((el) => {
                                return el.id == this.routeId
                            })
                            if (fi.length > 0) {
                                this.persons = fi[0].persons == null ? [] : fi[0].persons
                                this.links = fi[0].links == null ? [] : fi[0].links
                                this.relationName = fi[0].title
                                this.drawGraph()

                            } else {
                                this.$message({
                                    message: '找不到关系图谱',
                                    type: 'error',
                                    onClose: () => {
                                        this.$router.push({path: '/'})
                                    }
                                });
                            }

                        })
                    } else {
                        let fi = this.$store.state.relation.relation.filter((el) => {
                            return el.id == this.routeId
                        })
                        if (fi.length > 0) {
                            this.persons = fi[0].persons == null ? [] : fi[0].persons
                            this.links = fi[0].links == null ? [] : fi[0].links
                            this.relationName = fi[0].title
                            this.$nextTick(() => {
                                //this.drawGraph()
                                this.drawGraph()
                            })
                        } else {
                            this.$message({
                                message: '找不到关系图谱',
                                type: 'error',
                                onClose: () => {
                                    this.$router.push({path: '/'})
                                }
                            });
                        }

                    }

                },
                immediate: true
            },
        },
        computed: {
            whichTitle() {
                if (this.currentNode) {
                    return '修改' + this.currentNode.name + '信息'
                } else {
                    return '添加人物信息'
                }
            },
            whichTitleLink() {
                if (this.currentNode) {
                    if (this.currentLink) {
                        return '修改' + this.currentNode.name + '的人物关系网'
                    } else {
                        return '创建' + this.currentNode.name + '的人物关系网'
                    }
                }
            },
            linkList() {
                if (this.currentNode) {
                    return '管理' + this.currentNode.name + '的人物关系网'

                }
            },
            currentLinkList() {
                if (this.currentNode) {
                    let id = this.currentNode.id
                    let fi = this.links.filter((el) => {
                        return el.source.id == id || el.target.id == id
                    })
                    return fi
                }
            }
        },
        methods: {
            dynamicRect(selection) {
                selection.each(function () {
                    const rect = d3.select(this);
                    const gender = rect._groups[0][0].__data__.gender
                    const name = rect._groups[0][0].__data__.name
                    const rectWidth = rect._groups[0][0].__data__.textWidth

                    if (gender == '文字' && (rectWidth != undefined && rectWidth != 'auto')) {
                        rect.attr('width', (Number(rectWidth) + 30))
                            .attr('x', (Number(rectWidth) + 30) / -2)

                    } else {
                        rect.attr('width', name.length * 14 + 20)
                            .attr('x', (name.length * 14 + 20) / -2)

                    }
                });

            },
            wrapDynamicText(selection) {
                selection.each(function (el,index) {
                    const text = d3.select(this);
                    const gender = text._groups[0][0].__data__.gender
                    const textWidth = text._groups[0][0].__data__.textWidth
                    const textPo = text._groups[0][0].__data__.textPo
                    const maxWidth = textWidth
                    if (gender == '文字' && (textWidth != undefined && textWidth != 'auto')) {
                        const words = text.text().split('').reverse(); // 逐字拆分（中文必备）
                        let line = [];
                        const lineHeight = 1.4;
                        const x = text.attr("x");
                        let tspan = text.text('')
                            .attr('class','tspan')
                            .append("tspan")
                            .attr("x", x)
                            .attr("dy", "0em");

                        while (words.length) {
                            const word = words.pop();
                            line.push(word);
                            tspan.text(line.join(''));

                            // 超出宽度 → 换行
                            if (tspan.node().getComputedTextLength() > maxWidth && line.length > 1) {
                                line.pop();
                                tspan.text(line.join(''));
                                line = [word];
                                tspan = text.append("tspan")
                                    .attr("x", x)
                                    .attr("dy", lineHeight + "em")
                                    .text(word);
                            }
                        }


                    }

                    //console.log(text.selectAll('tspan').nodes().length)
                    const prevE=d3.select(this.previousElementSibling)
                    let num=text.selectAll('tspan').nodes().length
                    if(num===0){
                        prevE.attr('height',20)
                    }else{
                        prevE.attr('height',(num)*14*1.4+30)
                        if(textPo=='top'){
                            prevE.attr('y',((num)*14*1.4+30+4)*-1)
                            text.attr('y',((num)*14*1.4+4)*-1)
                        }
                    }


                });

            },
            toName(id) {
                let fii = this.persons.filter((el) => {
                    return el.id == id
                })
                return fii[0].name

            },
            getAngle(x1, y1, x2, y2) {
                const dx = x2 - x1;
                const dy = y2 - y1;

                let radian = Math.atan2(dy, dx);
                let angle = radian * 180 / Math.PI;

                if (angle < 0) {
                    angle += 360;
                }

                //
                if (angle > 90) {
                    angle += 180
                    if (angle > 450) {
                        angle -= 180
                    }
                }
                return angle;
            },
            getAngle1(x1, y1, x2, y2) {
                const dx = x2 - x1;
                const dy = y2 - y1;

                let radian = Math.atan2(dy, dx);
                let angle = radian * 180 / Math.PI;

                if (angle < 0) {
                    angle += 360;
                }
                return angle;
            },
            drawGraph() {
                const container = this.$refs.graphContainer
                d3.select(container).selectAll('*').remove()

                const width = window.innerWidth
                const height = window.innerHeight


                const svg = d3.select(container)
                    .append('svg')
                    .attr('width', width)
                    .attr('height', height)

                const simulation = d3.forceSimulation(this.persons)
                    .force('link', d3.forceLink(this.links).id(d => d.id).distance(120))
                    .force('charge', d3.forceManyBody().strength(-width / 2))
                    .force("x", d3.forceX(width / 2))
                    .force("y", d3.forceY(height / 2))
                //.force('center', d3.forceCenter(width / 2, height / 2))


                // 添加箭头标记定义

                const def = svg.append('defs')

                def.append('clipPath')
                    .attr('id', 'circle')
                    .append('circle')
                    .attr('r', 28)


                const link = svg.append('g')
                    .attr('id', 'line')
                    .selectAll('line')
                    .data(this.links)
                    .enter()
                    .append('line')
                    .attr('stroke', d => d.source.gender == '男' ? 'var(--green)' : d.source.gender == '女' ? 'var(--fen)' : d.source.gender == '无' ? 'var(--gray)' : d.source.color!=undefined?d.source.color:'var(--yellow)')
                    .attr('stroke-opacity', 0.6)


                const linkText = svg.append('g')
                    .attr('id', 'linkText')
                    .selectAll('text')
                    .data(this.links)
                    .enter()
                    .append('g')
                    .style('cursor', 'pointer')
                    .on("click", (event, d) => {
                        this.currentLink = d
                        this.showLinkDetails = true
                    })


                const lr = linkText.append('rect')
                    .attr('width', d => d.type.length * 11 + 11)
                    .attr('height', 20)
                    .attr('x', d => (d.type.length * 11 + 11) / -2)
                    .attr('y', -12)
                    .attr('rx', 5)
                    .attr("fill", '#fff')
                    .attr('stroke', '#aaa')
                    .attr('stroke-opacity', 0.6)

                const lt = linkText.append('text')
                    .text(d => d.type)
                    .attr('x', d => (d.type.length * 11) / -2)
                    .attr('y', 2.5)
                    .attr('font-size', '11px')
                    .attr('fill', '#444')
                    .attr("text-anchor", "center")

                const arrow = linkText.append('g')


                const arrowp = arrow.append('path')
                    .attr('d', d => `M${(d.type.length * 11 + 18) / 2},6L${(d.type.length * 11 + 36) / 2},0L${(d.type.length * 11 + 18) / 2},-6`)
                    .attr('fill', '#666')


                const node = svg.append('g')
                    .attr('id', 'node')
                    .selectAll('g')
                    .data(this.persons)
                    .enter()
                    .append('g')
                    .style('cursor', 'pointer')
                    .call(d3.drag()
                        .on('start', (event, d) => {
                            if (!event.active) simulation.alphaTarget(0.3).restart()
                            d.fx = d.x
                            d.fy = d.y
                        })
                        .on('drag', (event, d) => {
                            d.fx = event.x
                            d.fy = event.y
                        })
                        .on('end', (event, d) => {
                            // if (!event.active) simulation.alphaTarget(0)
                            // d.fx = null
                            // d.fy = null
                        })
                    ).on("click", (event, d) => {
                        //const {id, name, photo, gender, details, birthDate, deathDate} = d
                        //const cd = {id, name, photo, gender, details, birthDate, deathDate}
                        this.toolMenu(d)
                    }).on("mouseenter", (event, d) => {

                    });


                node.append('circle')
                    .attr('r', d => d.gender != '文字' ? 30 : 2)
                    .attr('fill', '#fff')
                    .attr('stroke', d => d.gender == '男' ? 'var(--green)' : d.gender == '女' ? 'var(--fen)' : d.gender == '无' ? 'var(--gray)' : d.color!=undefined?d.color:'var(--yellow)')
                    .attr('stroke-width', 2)

                node.append('image')
                    .attr('width', d => d.gender != '文字' ? 60 : 0)
                    .attr('height', d => d.gender != '文字' ? 60 : 0)
                    .attr('x', d => d.gender != '文字' ? -30 : 0)
                    .attr('y', d => d.gender != '文字' ? -30 : 0)
                    .attr('rx', d => d.gender != '文字' ? 30 : 0)
                    .attr('clip-path', 'url(#circle)')
                    .attr('href', d => d.photo ? d.photo : '')

                node.append('rect')
                    .attr('class','rect')
                    .attr('y', d => d.gender != '文字' ? 24 : (d.textWidth != 'auto' && d.textWidth != undefined) ? d.textPo=='top'?-4:4 : -24)
                    .attr('rx', 10)
                    .attr("fill", d => d.gender == '男' ? 'var(--green)' : d.gender == '女' ? 'var(--fen)' : d.gender == '无' ? 'var(--gray)' : d.color!=undefined?d.color:'var(--yellow)')
                    .call(this.dynamicRect);

                node.append('text')
                    .text(d => d.name)
                    .attr('text-anchor', 'middle')
                    .attr('x', 0)
                    .attr('y', d => d.gender != '文字' ? 40 : (d.textWidth != 'auto' && d.textWidth != undefined) ? d.textPo=='top'?-4:35 : -9)
                    .attr('fill', 'white')
                    .attr('font-size', '14')
                    .call(this.wrapDynamicText);


                node.append('text')
                    .text(d => d.alias)
                    .attr('text-anchor', 'middle')
                    .attr('y', d => d.gender != '文字' ? 58 : 14)
                    .attr('fill', 'var(--gray)')
                    .attr('font-size', '12')


                simulation.on('tick', () => {


                    link
                        .attr('x1', d => d.source.x)
                        .attr('y1', d => d.source.y)
                        .attr('x2', d => d.target.x)
                        .attr('y2', d => d.target.y)

                    linkText
                        .attr('transform', d => `translate(${(d.source.x + d.target.x) / 2},${(d.source.y + d.target.y) / 2})`)
                    lt
                        .attr('transform', d => `rotate(${this.getAngle(d.source.x, d.source.y, d.target.x, d.target.y)})`)
                    //.text(d => '(' + this.getAngle(d.source.x, d.source.y, d.target.x, d.target.y).toFixed(0))

                    lr
                        .attr('transform', d => `rotate(${this.getAngle(d.source.x, d.source.y, d.target.x, d.target.y)})`)

                    // arrow
                    //     .attr('transform', d => `translate(${(d.type.length * 11 + 22) / 2},0) rotate(${this.getAngle1(d.source.x, d.source.y, d.target.x, d.target.y)})`)

                    arrow
                        .attr('transform', d => `rotate(${this.getAngle1(d.source.x, d.source.y, d.target.x, d.target.y)})`)

                    node
                        .attr('transform', d => `translate(${d.x},${d.y})`)
                })
            },
            async handleRemove() {
                this.editForm.photo = ''
                let arr = this.currentNode.photo.split('/')
                let len = arr.length
                const {data} = await this.$supabase
                    .storage
                    .from('my')
                    .remove(arr[len - 1])
                this.$message.success('头像删除成功！');
            },
            async handleAvatarSuccess(res, file) {
                const {error} = await this.$supabase
                    .storage
                    .from('my')
                    .upload(file.name, file.raw)
                if (error) {
                    this.$message.error(error);
                } else {
                    this.$message.success('头像上传成功！');
                    const {data} = await this.$supabase
                        .storage
                        .from('my')
                        .getPublicUrl(file.name)
                    this.editForm.photo = data.publicUrl
                }

            },
            beforeAvatarUpload(file) {
                let types = ['image/jpeg', 'image/png', 'image/gif']
                const isJPG = types.indexOf(file.type) > -1;
                const isLt2M = file.size / 1024 / 1024 < 2;

                if (!isJPG) {
                    this.$message.error('上传头像只能是jpg,png,gif图片格式!');
                }
                if (!isLt2M) {
                    this.$message.error('上传头像图片大小不能超过2MB!');
                }
                return isJPG && isLt2M;
            },
            saveImg() {
                let x = 0
                let y = 0
                if (this.captureWidth > window.innerWidth) {
                    x += (window.innerWidth - this.captureWidth) * 0.5
                } else {
                    x += (window.innerWidth - this.captureWidth) * 0.5
                }

                html2canvas(document.querySelector('.tree-container'), {
                    useCORS: true,
                    width: this.captureWidth + 120,
                    height: this.captureHeight + 120,
                    x: x - 60,
                    y: y - 60,
                    backgroundColor: window.getComputedStyle(document.body).backgroundColor
                }).then((canvas) => {
                    let lastpic
                    canvas.toBlob((blob) => {
                        lastpic = URL.createObjectURL(blob)
                        let eleLink = document.createElement('a');
                        eleLink.download = this.relationName + '族谱';
                        eleLink.style.display = 'none';
                        eleLink.href = lastpic;
                        eleLink.click();
                    }, 'image/png', 1);
                });
            },
            toolMenu(node) {
                this.currentNode = node
                this.showToolMenu = true
            },
            addLink() {
                this.editLinksMode = 'add'
                this.showLink = true
                this.currentLink = ''//很重要
                this.linkForm.target = ''
                this.linkForm.type = ''
                this.linkForm.details = ''
            },
            editLink(node) {
                this.editLinksMode = 'edit'
                this.showLink = true
                this.currentLink = node
                this.linkForm.source = node.source.name
                this.linkForm.target = node.target.name
                this.linkForm.type = node.type
                this.linkForm.details = node.details
            },
            deleteLink(node) {
                const index = this.getIndex(this.links, node)
                if (index > -1) {
                    this.links.splice(index, 1)
                    this.drawGraph()
                }
                this.$message({
                    message: '删除成功',
                    type: 'success'
                });
                this.saveRelation('links')
            },
            listLink() {
                this.showLinkList = true
            },
            addPerson() {
                this.editPersonsMode = 'add'
                this.showPerson = true
                let xb = '男'
                this.editForm = {
                    photo: '',
                    name: '',
                    alias: '',
                    gender: xb,
                    textWidth: 'auto',
                    textPo: 'bottom',
                    color: '#fa0',
                    birthDate: '',
                    deathDate: '',
                    details: '',
                }
            },
            getIndex(arr, obj) {
                let index = null;
                let key = Object.keys(obj)[0];
                arr.every(function (value, i) {
                    if (value[key] === obj[key]) {
                        index = i;
                        return false;
                    }
                    return true;
                });
                return index;
            },
            async deleteNode() {
                //person
                let node = this.currentNode
                const index = this.getIndex(this.persons, node)
                if (index > -1) {
                    this.persons.splice(index, 1)
                    this.drawGraph()
                }
                //storage
                let arr = node.photo.split('/')
                let len = arr.length
                await this.$supabase
                    .storage
                    .from('my')
                    .remove(arr[len - 1])
                //links

                let delList = []
                let fi = this.links.filter((el) => {
                    return el.source.id == node.id || el.target.id == node.id
                })
                if (fi.length > 0) {
                    fi.forEach((el) => {
                        delList.push(el.index)
                    })
                    let k = 0;
                    for (let j in delList.sort()) {
                        this.links.splice(delList[j] - k, 1);
                        k++;
                    }
                    this.drawGraph()
                }


                this.$message({
                    message: '删除成功',
                    type: 'success'
                });
                this.showToolMenu = false
                this.saveRelation('links')
                this.saveRelation('persons')
            },
            editPerson() {
                this.showPerson = true
                this.editPersonsMode = 'edit'
                this.editForm = {
                    photo: this.currentNode.photo,
                    name: this.currentNode.name,
                    alias: this.currentNode.alias,
                    gender: this.currentNode.gender,
                    textWidth: this.currentNode.textWidth,
                    textPo: this.currentNode.textPo,
                    color: this.currentNode.color,
                    birthDate: this.currentNode.birthDate,
                    deathDate: this.currentNode.deathDate,
                    details: this.currentNode.details,
                }
            },
            async saveRelation(text) {
                if (text == 'persons') {
                    await this.$supabase.from('relation').update({'persons': this.persons}).eq('id', this.routeId)
                }
                if (text == 'links') {
                    const links = []
                    this.links.forEach((el) => {
                        links.push({source: el.source.id, target: el.target.id, type: el.type, details: el.details})
                    })
                    await this.$supabase.from('relation').update({'links': links}).eq('id', this.routeId)
                }

                await this.$store.dispatch('relation/getAll')

            },

            submitForm1(formName) {
                this.$refs[formName].validate((valid) => {
                    if (valid) {
                        const source = this.persons.find(n => n.name === this.linkForm.source)
                        const target = this.persons.find(n => n.name === this.linkForm.target)
                        if (source && target) {
                            this.$message({
                                message: '添加成功',
                                type: 'success'
                            });
                            this.saveLinks(source, target)
                        } else {
                            this.$message({
                                message: '人物不存在',
                                type: 'error'
                            });
                        }

                    } else {
                        return false;
                    }
                });
            },
            submitForm(formName) {
                this.$refs[formName].validate((valid) => {
                    if (valid) {
                        this.$message({
                            message: '添加成功',
                            type: 'success'
                        });
                        this.savePersons()

                    } else {
                        return false;
                    }
                });
            },
            savePersons() {
                if (this.editPersonsMode === 'add') {
                    const newNode = {
                        id: Date.now(),
                        photo: this.editForm.photo,
                        name: this.editForm.name,
                        alias: this.editForm.alias,
                        gender: this.editForm.gender,
                        textWidth: this.editForm.textWidth,
                        textPo: this.editForm.textPo,
                        color: this.editForm.color,
                        birthDate: this.editForm.birthDate,
                        deathDate: this.editForm.deathDate,
                        details: this.editForm.details,
                    }
                    this.persons.push(newNode)
                    this.drawGraph()


                } else if (this.editPersonsMode === 'edit' && this.currentNode) {
                    this.currentNode.photo = this.editForm.photo
                    this.currentNode.name = this.editForm.name
                    this.currentNode.alias = this.editForm.alias
                    this.currentNode.gender = this.editForm.gender
                    this.currentNode.textWidth = this.editForm.textWidth
                    this.currentNode.textPo = this.editForm.textPo
                    this.currentNode.color = this.editForm.color
                    this.currentNode.birthDate = this.editForm.birthDate
                    this.currentNode.deathDate = this.editForm.deathDate
                    this.currentNode.details = this.editForm.details
                    this.drawGraph()
                }
                this.saveRelation('persons')
                this.showPerson = false
                //this.showToolMenu = false
            },
            saveLinks(source, target) {
                if (this.editLinksMode === 'add') {
                    const newNode = {
                        source: source.id,
                        target: target.id,
                        type: this.linkForm.type,
                        details: this.linkForm.details,
                    }
                    this.links.push(newNode)
                    this.drawGraph()

                } else if (this.editLinksMode === 'edit') {
                    this.currentLink.source.name = this.linkForm.source
                    this.currentLink.target.name = this.linkForm.target
                    this.currentLink.type = this.linkForm.type
                    this.currentLink.details = this.linkForm.details
                    this.drawGraph()
                }
                this.saveRelation('links')
                this.showLink = false
                //this.showToolMenu = false
            },
        }
    }
</script>
